mapper.select:


    del_flag = '0'

        and (
            name_cn ILIKE CONCAT('%', #{searchQuery}, '%')
            or name_native ILIKE CONCAT('%', #{searchQuery}, '%')
            or province ILIKE CONCAT('%', #{searchQuery}, '%')
            or developer ILIKE CONCAT('%', #{searchQuery}, '%')
        )


        and region = #{region}


        and province = #{province}


        and park_level = #{parkLevel}


        and verification_status = #{verificationStatus}


        and dominant_industries @> jsonb_build_array(#{dominantIndustry})


        and land_rent_usd_per_sqm <= #{maxLandRent}


        and occupancy_rate >= #{minOccupancy}


        and distance_to_sea_port_km <= #{maxDistancePort}


        and is_sez = true


order by update_time desc nulls last, name_cn asc
